// Allowed characters: horizontal tabs, spaces or visible ascii characters: https://www.rfc-editor.org/rfc/rfc7230#section-3.1.2
// eslint-disable-next-line no-control-regex
const DISALLOWED_STATUS_CHARS = /[^\u0009\u0020-\u007E]/g;

/**
 * Make sure the status message is safe to use in a response.
 *
 * Allowed characters: horizontal tabs, spaces or visible ascii characters: https://www.rfc-editor.org/rfc/rfc7230#section-3.1.2
 */
export function sanitizeStatusMessage(statusMessage = ""): string {
  return statusMessage.replace(DISALLOWED_STATUS_CHARS, "");
}

/**
 * Make sure the status code is a valid HTTP status code.
 */
export function sanitizeStatusCode(statusCode?: string | number, defaultStatusCode = 200): number {
  if (!statusCode) {
    return defaultStatusCode;
  }
  if (typeof statusCode === "string") {
    statusCode = +statusCode;
  }
  // `Number.isInteger` rejects everything a bare range check would let through: `NaN` (from
  // `+statusCode` on a non-numeric string), floats, and non-numeric values such as objects or
  // arrays, whose comparisons are all `false`. Without it an invalid code leaks through and
  // breaks `Response`.
  if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
    return defaultStatusCode;
  }
  return statusCode;
}
import { EmptyObject } from "./obj.ts";

/**
 * Checks if a certain input has a given property.
 * @param obj - The input to check.
 * @param prop - The property to check for.
 * @returns A boolean indicating whether the input is an object and has the property.
 */
export function hasProp(obj: any, prop: string | symbol): boolean {
  try {
    return prop in obj;
  } catch {
    return false;
  }
}

export function isJSONSerializable(value: any, _type: string): boolean {
  // Primitive values are JSON serializable
  if (value === null || value === undefined) {
    return true;
  }
  if (_type !== "object") {
    return _type === "boolean" || _type === "number" || _type === "string";
  }

  // Objects with `toJSON` are JSON serializable
  if (typeof value.toJSON === "function") {
    return true;
  }

  // Arrays are JSON serializable (we assume items are safe too!)
  if (Array.isArray(value)) {
    return true;
  }

  // Pipable streams are not JSON serializable (react pipe result is pure object :()
  if (typeof value.pipe === "function" || typeof value.pipeTo === "function") {
    return false;
  }

